def apply(inputs, premises):
    question = inputs["current_question"]
    nondisclosure_clauses = premises["nondisclosure_clauses"]
    party_definitions = premises["party_and_recipient_definitions"]
    role_context = False
    for definition_text in party_definitions:
        if "Receiving Party" in definition_text or "RECIPIENT" in definition_text or "Volunteer" in definition_text or "Party" in definition_text:
            role_context = True
    general_third_party_prohibition = False
    employee_permission = False
    professional_advisor_permission = False
    for clause_text in nondisclosure_clauses:
        prohibits_third_parties = "divulge any Confidential Information to third parties" in clause_text or "not to disclose such Confidential Information to third parties" in clause_text or "shall not disclose, allow access to, transmit or transfer the Confidential Information to any third party" in clause_text
        if prohibits_third_parties:
            general_third_party_prohibition = True
        express_permission = "may disclose" in clause_text
        confidentiality_condition = "bound by obligations of confidentiality" in clause_text or "treat the Confidential Information as confidential" in clause_text
        need_condition = "need to know" in clause_text
        purpose_condition = "Business Purpose" in clause_text or "for the Purpose" in clause_text
        qualified_permission = express_permission and confidentiality_condition and need_condition and purpose_condition
        if qualified_permission and "employees" in clause_text:
            employee_permission = True
        if qualified_permission and ("legal advisors" in clause_text or "financial advisors" in clause_text or "accountants" in clause_text):
            professional_advisor_permission = True
    category_match = False
    if "employees" in question and employee_permission:
        category_match = True
    if "professional advisors" in question and professional_advisor_permission:
        category_match = True
    exception_applies = role_context and category_match
    general_third_party_prohibition = role_context and general_third_party_prohibition
    return {"exception_applies": exception_applies, "general_third_party_prohibition": general_third_party_prohibition}

def apply(inputs, premises):
    question = inputs["current_question"]
    is_disclosure_permission_query = "Receiving Party" in question and "may share some Confidential Information" in question
    if not is_disclosure_permission_query:
        answer = "NotMentioned"
    elif inputs["representative_exception_applies"]:
        answer = "Entailment"
    elif inputs["general_third_party_prohibition"] and "some third-parties" in question:
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}
